using System.ComponentModel.DataAnnotations; using System.ComponentModel.DataAnnotations.Schema; using LibrarySystem.Domain.Catalog; using Microsoft.EntityFrameworkCore;
namespace LibrarySystem.Infrastructure.Catalog;
[Table("AcquisitionBudgets"),Index(nameof(Year),IsUnique=true)] public sealed class AcquisitionBudget { [Key] public int Id{get;set;} public int Year{get;set;} [Precision(18,2)] public decimal AllocatedAmount{get;set;} [Timestamp] public byte[] RowVersion{get;set;}=[]; }
[Table("AcquisitionRecords"),Index(nameof(OrderNumber),IsUnique=true)] public sealed class AcquisitionRecord { [Key] public long Id{get;set;} [Required,MaxLength(100)] public required string OrderNumber{get;set;} public long BookId{get;set;} [ForeignKey(nameof(BookId)),DeleteBehavior(DeleteBehavior.Restrict)] public required Book Book{get;set;} public AcquisitionSource Source{get;set;} [MaxLength(200)] public string? DonationSource{get;set;} public int QuantityOrdered{get;set;} [Precision(18,2)] public decimal UnitCost{get;set;} public AcquisitionStatus Status{get;set;}=AcquisitionStatus.Draft; [Precision(0)] public DateTime CreatedAtUtc{get;set;}=DateTime.UtcNow; [Timestamp] public byte[] RowVersion{get;set;}=[]; public ICollection<AcquisitionReceipt> Receipts{get;set;}=[]; }
[Table("AcquisitionReceipts"),Index(nameof(BookCopyId),IsUnique=true)] public sealed class AcquisitionReceipt { [Key] public long Id{get;set;} public long AcquisitionRecordId{get;set;} [ForeignKey(nameof(AcquisitionRecordId)),DeleteBehavior(DeleteBehavior.Restrict)] public required AcquisitionRecord AcquisitionRecord{get;set;} public long BookCopyId{get;set;} [ForeignKey(nameof(BookCopyId)),DeleteBehavior(DeleteBehavior.Restrict)] public required BookCopy BookCopy{get;set;} [Precision(0)] public DateTime ReceivedAtUtc{get;set;}=DateTime.UtcNow; [MaxLength(450)] public string? ReceivedByUserId{get;set;} }
